const config = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "postgresql",
  "inlineSchema": "// IR2F — Plateforme de formation LGEF\n// Schema dédié \"ir2f\", isolé de public/auth\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  schemas  = [\"ir2f\"]\n}\n\n// ─── ENUMS ───────────────────────────────────────────\n\nenum Role {\n  STAGIAIRE\n  FORMATEUR\n  ADMIN\n  DIRECTION\n\n  @@schema(\"ir2f\")\n}\n\nenum StatutInscription {\n  EN_ATTENTE\n  VALIDEE\n  REFUSEE\n\n  @@schema(\"ir2f\")\n}\n\nenum TypeFormation {\n  PRESENTIEL\n  VISIO\n  ELEARNING\n  MIXTE\n\n  @@schema(\"ir2f\")\n}\n\nenum StatutFormation {\n  BROUILLON\n  PUBLIEE\n  ARCHIVEE\n\n  @@schema(\"ir2f\")\n}\n\nenum CategorieFormation {\n  EDUCATEUR\n  ARBITRAGE\n  TERRAIN\n  CLUB\n  DEV\n\n  @@schema(\"ir2f\")\n}\n\nenum Filiere {\n  PROFESSIONNELLE\n  BENEVOLE\n\n  @@schema(\"ir2f\")\n}\n\n// Groupe d'appartenance dans le diagramme \"équivalences et passerelles\"\n// (page /formations, onglet Éducateur). Null = formation hors diagramme.\nenum GroupeEquivalence {\n  AF\n  CFI\n  DF\n  CERTIF\n  PRO_TOP\n  PRO_MID\n  PRO_BEF\n  PRO_BEF_TRAD\n  PRO_BEF_APP\n  PRO_BEF_VAE\n  PRO_BMF\n  PRO_BMF_TRAD\n  PRO_BMF_APP\n  PRO_BMF_VAE\n  PRO_MID2\n  PRO_BOTTOM\n  PRO_BOTTOM_TRAD\n  PRO_BOTTOM_APP\n  CLUB_VIVRE\n  CLUB_GERER\n  CLUB_DEV\n\n  @@schema(\"ir2f\")\n}\n\nenum VarianteNode {\n  NAVY\n  LIGHT\n  RED\n  OUTLINE\n\n  @@schema(\"ir2f\")\n}\n\nenum DocumentCategorie {\n  ADMINISTRATIF\n  PEDAGOGIQUE\n\n  @@schema(\"ir2f\")\n}\n\nenum StatutCovoiturage {\n  OUVERT\n  COMPLET\n  ANNULE\n\n  @@schema(\"ir2f\")\n}\n\n// Mode d'inscription à une formation : formulaire interne IR2F, ou\n// redirection vers le portail d'inscription de la FFF (IR2F gère alors\n// uniquement les documents internes — convention de stage, etc.)\nenum ModeInscription {\n  INTERNE\n  PORTAIL_FFF\n\n  @@schema(\"ir2f\")\n}\n\n// Origine d'une inscription — permet de distinguer les inscriptions\n// enregistrées en interne de celles capturées avant redirection vers la FFF\nenum OrigineInscription {\n  INTERNE\n  FFF_STAGIAIRE\n  FFF_CLUB\n\n  @@schema(\"ir2f\")\n}\n\n// Type de lien pour les boutons configurables de l'accueil (bandeau emploi)\nenum TypeLien {\n  INTERNE\n  EXTERNE\n\n  @@schema(\"ir2f\")\n}\n\n// Les 5 étapes du circuit de signature d'une convention de stage, dans cet\n// ordre : le stagiaire signe d'abord, puis le document circule automatiquement\n// vers le club, le tuteur, le maître de stage et enfin le responsable pédagogique.\nenum RoleSignataire {\n  STAGIAIRE\n  CLUB\n  TUTEUR\n  MAITRE_DE_STAGE\n  RESPONSABLE_PEDAGOGIQUE\n\n  @@schema(\"ir2f\")\n}\n\nenum StatutSignature {\n  NON_ENVOYE\n  EN_ATTENTE\n  SIGNE\n  REFUSE\n\n  @@schema(\"ir2f\")\n}\n\nenum RenvoiCanal {\n  MAIL\n  WHATSAPP\n\n  @@schema(\"ir2f\")\n}\n\n// ─── UTILISATEURS ────────────────────────────────────\n\nmodel User {\n  id        String   @id @default(uuid())\n  email     String   @unique\n  nom       String\n  prenom    String\n  telephone String?\n  password  String?\n  role      Role     @default(STAGIAIRE)\n  actif     Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  inscriptions                   Inscription[]\n  documentsUpload                Document[]\n  documentsRecus                 DocumentDestinataire[]\n  signatures                     Signature[]\n  messagesEnvoyes                Message[]              @relation(\"Expediteur\")\n  messagesRecus                  MessageDestinataire[]\n  covoituragesConduit            Covoiturage[]          @relation(\"Conducteur\")\n  covoituragesPassager           CovoituragePassager[]\n  articles                       Article[]\n  demandesInscription            DemandeInscription[]\n  formationsEnCharge             FormationFormateur[]\n  sessionsResponsablePedagogique Session[]              @relation(\"SessionResponsablePedagogique\")\n\n  @@schema(\"ir2f\")\n}\n\n// ─── FORMATIONS ──────────────────────────────────────\n\nmodel Formation {\n  id          String  @id @default(uuid())\n  slug        String  @unique\n  titre       String\n  description String?\n\n  // Si renseigné, la fiche publique de cette formation (/formations/[slug]) redirige\n  // directement vers ce lien externe au lieu de s'afficher — pour les formations gérées\n  // entièrement ailleurs (ex. portail FFF) dont IR2F n'affiche qu'une tuile d'entrée. Le reste du\n  // contenu de la formation (programme, sessions...) peut rester renseigné sans effet, au cas où\n  // ce lien serait retiré plus tard.\n  lienExterne   String?\n  type          TypeFormation\n  statut        StatutFormation @default(BROUILLON)\n  dureeHeures   Int?\n  dureeLabel    String?\n  modeLabel     String?\n  lieu          String?\n  prix          Float?\n  places        Int?\n  lienVisio     String?\n  image         String?\n  programme     Json?\n  formateurNom  String?\n  formateurRole String?\n  ordre         Int             @default(0)\n\n  categorie            CategorieFormation @default(EDUCATEUR)\n  filiere              Filiere?\n  cpfEligible          Boolean            @default(false)\n  fafaEligible         Boolean            @default(false)\n  bonFormationEligible Boolean            @default(false)\n\n  // Inscription via le portail FFF (externe à IR2F) — lien distinct selon\n  // que ce soit le stagiaire ou le club qui réalise l'inscription.\n  // fffCaptureActif : si activé, on capture nom/prénom/email/téléphone avant\n  // de rediriger vers la FFF ; sinon, redirection directe vers le lien FFF.\n  modeInscription  ModeInscription @default(INTERNE)\n  lienFffStagiaire String?\n  lienFffClub      String?\n  fffCaptureActif  Boolean         @default(true)\n\n  // Période globale de la formation (« du ... au ... »), affichée sur la fiche publique à côté de\n  // la durée — indépendante des sessions (qui peuvent être plus fines) et n'alimente plus la\n  // convention de stage (voir Session.dateDebut/dateFin/lieu, propres à chaque session).\n  dateDebut DateTime?\n  dateFin   DateTime?\n\n  // Diagramme \"équivalences et passerelles\" — null si hors diagramme\n  groupeEquivalence GroupeEquivalence?\n  varianteNode      VarianteNode?\n  badgeNode         String?\n  shortNode         String?\n\n  // Indicateurs de résultats (type Qualiopi) affichés sur la fiche publique\n  tauxReussite     String?\n  tauxSatisfaction String?\n  resultats        Json? // [{ annee, tauxSelection, tauxJuryFinal }]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  sessions             Session[]\n  inscriptions         Inscription[]\n  demandes             DemandeInscription[]\n  documents            Document[]\n  heroSlides           HeroSlide[]\n  formateurs           FormationFormateur[]\n  messages             Message[]\n  covoiturages         Covoiturage[]\n  ongletsVedette       FormationOnglet[]\n  tutorielsInscription TutorielInscription[]\n\n  conventionStagiaires ConventionStagiaire[]\n\n  @@schema(\"ir2f\")\n}\n\nmodel FormationFormateur {\n  id          String   @id @default(uuid())\n  userId      String\n  formationId String\n  createdAt   DateTime @default(now())\n\n  user      User      @relation(fields: [userId], references: [id])\n  formation Formation @relation(fields: [formationId], references: [id])\n\n  @@unique([userId, formationId])\n  @@schema(\"ir2f\")\n}\n\nmodel Session {\n  id          String   @id @default(uuid())\n  formationId String\n  dateDebut   DateTime\n  dateFin     DateTime\n  lieu        String?\n  lienVisio   String?\n  places      Int?\n  createdAt   DateTime @default(now())\n\n  formation Formation @relation(fields: [formationId], references: [id])\n\n  // Convention de stage : modèle PDF associé + responsable pédagogique, propres à CETTE session\n  // (une formation peut avoir plusieurs sessions avec des stagiaires, dates et responsables\n  // différents — voir ConventionStagiaire.sessionId). Même mécanique que l'ancien portage sur\n  // Formation : le responsable pédagogique signe UNE SEULE FOIS pour toute la session (pas par\n  // stagiaire), via un lien à token ; sa signature est ensuite incrustée automatiquement dans le\n  // PDF de chaque stagiaire de cette session au moment de sa génération.\n  conventionTemplateId                       String?\n  conventionTemplate                         ConventionTemplate? @relation(fields: [conventionTemplateId], references: [id])\n  responsablePedagogiqueUserId               String?\n  responsablePedagogiqueUser                 User?               @relation(\"SessionResponsablePedagogique\", fields: [responsablePedagogiqueUserId], references: [id])\n  responsablePedagogiqueSignatureToken       String?             @unique\n  responsablePedagogiqueSignatureEnvoyeAt    DateTime?\n  responsablePedagogiqueSignatureSignedAt    DateTime?\n  responsablePedagogiqueSignatureStoragePath String?\n  responsablePedagogiqueSignatureIpAddress   String?\n  responsablePedagogiqueSignatureUserAgent   String?\n\n  conventionStagiaires ConventionStagiaire[]\n\n  @@schema(\"ir2f\")\n}\n\n// ─── INSCRIPTIONS ────────────────────────────────────\n\nmodel Inscription {\n  id          String             @id @default(uuid())\n  userId      String\n  formationId String\n  statut      StatutInscription  @default(EN_ATTENTE)\n  origine     OrigineInscription @default(INTERNE)\n  createdAt   DateTime           @default(now())\n  updatedAt   DateTime           @updatedAt\n\n  user      User      @relation(fields: [userId], references: [id])\n  formation Formation @relation(fields: [formationId], references: [id])\n\n  @@unique([userId, formationId])\n  @@schema(\"ir2f\")\n}\n\nmodel DemandeInscription {\n  id          String            @id @default(uuid())\n  nom         String\n  prenom      String\n  email       String\n  telephone   String?\n  message     String?\n  formationId String?\n  userId      String?\n  statut      StatutInscription @default(EN_ATTENTE)\n  createdAt   DateTime          @default(now())\n  updatedAt   DateTime          @updatedAt\n\n  formation Formation? @relation(fields: [formationId], references: [id])\n  user      User?      @relation(fields: [userId], references: [id])\n\n  @@schema(\"ir2f\")\n}\n\n// Demande envoyée depuis le formulaire \"Je souhaite être contacté\" de l'accueil —\n// distincte de DemandeInscription qui déclenche un vrai workflow d'inscription\n// (validation, création de compte). Ici : simple prise de contact, sans compte.\nmodel DemandeContact {\n  id         String   @id @default(uuid())\n  thematique String\n  nom        String\n  prenom     String\n  email      String\n  telephone  String?\n  message    String?\n  createdAt  DateTime @default(now())\n\n  @@schema(\"ir2f\")\n}\n\n// ─── DOCUMENTS ───────────────────────────────────────\n\nmodel Document {\n  id                String            @id @default(uuid())\n  nom               String\n  url               String?\n  storagePath       String?\n  taille            Int?\n  mimeType          String?\n  uploaderId        String\n  formationId       String?\n  public            Boolean           @default(false)\n  // Distinct de `public` (partage avec les stagiaires connectés) : affiche ce document\n  // dans le bloc \"Documents utiles\" de la fiche formation publique (site vitrine).\n  visiblePublic     Boolean           @default(false)\n  ordre             Int               @default(0)\n  rolesRequis       Role[]            @default([STAGIAIRE])\n  categorie         DocumentCategorie @default(ADMINISTRATIF)\n  // Si vrai, le document n'est visible que par les destinataires listés ci-dessous\n  // (au lieu de l'ensemble des stagiaires validés de la formation).\n  partageIndividuel Boolean           @default(false)\n  createdAt         DateTime          @default(now())\n\n  uploader      User                   @relation(fields: [uploaderId], references: [id])\n  formation     Formation?             @relation(fields: [formationId], references: [id])\n  signatures    Signature[]\n  messages      Message[]\n  destinataires DocumentDestinataire[]\n\n  @@schema(\"ir2f\")\n}\n\nmodel DocumentDestinataire {\n  id         String @id @default(uuid())\n  documentId String\n  userId     String\n\n  document Document @relation(fields: [documentId], references: [id])\n  user     User     @relation(fields: [userId], references: [id])\n\n  @@unique([documentId, userId])\n  @@schema(\"ir2f\")\n}\n\nmodel Signature {\n  id           String   @id @default(uuid())\n  documentId   String\n  userId       String\n  signedAt     DateTime @default(now())\n  signatureUrl String?\n  consentText  String?\n  ipAddress    String?\n  userAgent    String?\n  documentHash String?\n\n  document Document @relation(fields: [documentId], references: [id])\n  user     User     @relation(fields: [userId], references: [id])\n\n  @@unique([documentId, userId])\n  @@schema(\"ir2f\")\n}\n\n// ─── CONVENTIONS DE STAGE ────────────────────────────\n\n// Bibliothèque de modèles PDF réutilisables entre sessions. Chaque modèle\n// est un PDF fillable (champs de formulaire nommés selon le contrat documenté\n// dans src/lib/conventions/variables.ts) que l'admin associe à une session.\nmodel ConventionTemplate {\n  id          String   @id @default(uuid())\n  nom         String\n  storagePath String\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  sessions Session[]\n\n  @@schema(\"ir2f\")\n}\n\n// Organigramme IR2F affiché en pièce jointe sur la page /contact — une seule ligne\n// (id fixe \"singleton\"), remplacée à chaque nouvel upload depuis l'admin.\nmodel Organigramme {\n  id          String   @id @default(uuid())\n  nom         String\n  storagePath String\n  updatedAt   DateTime @updatedAt\n\n  @@schema(\"ir2f\")\n}\n\n// Annuaire des clubs FFF (import périodique depuis l'export LGEF, voir\n// src/lib/actions/clubs.ts) — sert à pré-remplir l'adresse et le représentant par défaut du club\n// d'accueil à l'import des stagiaires (ConventionStagiaire.club*/clubRepresentant* est une copie\n// figée à l'import, pas une référence : la convention déjà générée ne doit pas bouger si\n// l'annuaire est réimporté plus tard). referentNom/referentPrenom viennent de la colonne\n// \"correspondant\" de l'export LGEF — pas forcément la personne habilitée à signer une convention,\n// donc simple valeur par défaut modifiable par le club lui-même au moment de sa signature.\nmodel Club {\n  id                String   @id @default(uuid())\n  nom               String   @unique\n  numeroAffiliation String?\n  adresse           String?\n  cp                String?\n  ville             String?\n  email             String?\n  referentNom       String?\n  referentPrenom    String?\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  @@schema(\"ir2f\")\n}\n\n// Un stagiaire importé via Excel pour les besoins de la convention de stage d'une formation\n// (gabarit LGEF : club d'accueil, stagiaire, tuteur, maître de stage — voir\n// src/lib/actions/convention-stagiaires.ts pour le mapping exact des colonnes). Pas de compte\n// User associé (signature par lien à token, pas de connexion à IR2F) — voir ConventionSignataire.\n// Le tuteur et le maître de stage sont propres à chaque stagiaire (varient selon son club\n// d'accueil) ; seul le responsable pédagogique est fixe pour la formation (voir Formation).\nmodel ConventionStagiaire {\n  id          String @id @default(uuid())\n  formationId String\n  // Dénormalisé à partir de session.formationId (jamais accepté indépendamment en entrée) : sert\n  // au roster formateur/admin qui couvre toute la formation, toutes sessions confondues (voir\n  // getConventionStagiairesForRoster) sans avoir à joindre Session pour chaque lecture.\n  sessionId   String\n\n  // Club d'accueil — nom/numéro/email saisis dans l'Excel stagiaires ; adresse déduite de\n  // l'annuaire Club au moment de l'import (voir Club ci-dessus), puis confirmée/corrigée par le\n  // club lui-même au moment de sa signature ; représentant renseigné par le club à cette même\n  // étape (article 1), pas connu à l'import.\n  club                    String?\n  numeroAffiliationClub   String?\n  emailClub               String?\n  clubAdresse             String?\n  clubCp                  String?\n  clubVille               String?\n  clubRepresentantNom     String?\n  clubRepresentantQualite String?\n\n  // Stagiaire\n  civilite      String?\n  nom           String\n  prenom        String\n  dateNaissance String?\n  adresse       String?\n  cp            String?\n  ville         String?\n  telephone     String?\n  email         String\n\n  // Tuteur — nom/prénom/email saisis dans l'Excel stagiaires ; le reste renseigné par le tuteur\n  // lui-même au moment de sa signature.\n  tuteurNom           String?\n  tuteurPrenom        String?\n  tuteurEmail         String?\n  tuteurQualite       String?\n  tuteurAdresse       String?\n  tuteurCp            String?\n  tuteurVille         String?\n  tuteurTelephone     String?\n  tuteurQualification String?\n\n  // Maître de stage (propre à ce stagiaire) — qualité renseignée par le maître de stage lui-même\n  // au moment de sa signature.\n  maitreDeStageNom     String?\n  maitreDeStagePrenom  String?\n  maitreDeStageAdresse String?\n  maitreDeStageCp      String?\n  maitreDeStageVille   String?\n  maitreDeStageEmail   String?\n  maitreDeStageQualite String?\n\n  // Réponses saisies par le stagiaire au moment de sa signature (article 3 de la convention)\n  natureIntervention           String[]\n  natureInterventionAutre      String?\n  publicVise                   String?\n  publicNiveauSportif          String?\n  objectifEncadrementSeul      Boolean?\n  objectifEncadrementAutonomie Boolean?\n  objectifEncadrementPonctuel  Boolean?\n\n  donneesSupplementaires Json?\n  pdfStoragePath         String?\n  envoyeAt               DateTime?\n  completedAt            DateTime?\n  createdAt              DateTime  @default(now())\n\n  formation   Formation              @relation(fields: [formationId], references: [id])\n  session     Session                @relation(fields: [sessionId], references: [id])\n  signataires ConventionSignataire[]\n\n  @@unique([sessionId, email])\n  @@schema(\"ir2f\")\n}\n\n// Une étape du circuit de signature (5 lignes par ConventionStagiaire, une\n// par RoleSignataire). Le signataire accède via un lien à token — aucun\n// compte requis, y compris pour le stagiaire lui-même.\nmodel ConventionSignataire {\n  id                    String          @id @default(uuid())\n  conventionStagiaireId String\n  role                  RoleSignataire\n  ordre                 Int\n  nom                   String\n  email                 String\n  token                 String          @unique @default(uuid())\n  statut                StatutSignature @default(NON_ENVOYE)\n  envoyeAt              DateTime?\n  signedAt              DateTime?\n  refusedAt             DateTime?\n  motifRefus            String?\n  signatureStoragePath  String?\n  ipAddress             String?\n  userAgent             String?\n  documentHash          String?\n\n  // Trace du dernier renvoi manuel (bouton mail/whatsapp) — qui, quand, par quel canal\n  dernierRenvoiPar   String?\n  dernierRenvoiCanal RenvoiCanal?\n  dernierRenvoiAt    DateTime?\n\n  conventionStagiaire ConventionStagiaire @relation(fields: [conventionStagiaireId], references: [id])\n\n  @@unique([conventionStagiaireId, role])\n  @@schema(\"ir2f\")\n}\n\n// ─── MESSAGERIE ──────────────────────────────────────\n\nmodel Message {\n  id           String   @id @default(uuid())\n  expediteurId String\n  sujet        String?\n  contenu      String\n  formationId  String?\n  documentId   String?\n  createdAt    DateTime @default(now())\n\n  expediteur    User                  @relation(\"Expediteur\", fields: [expediteurId], references: [id])\n  destinataires MessageDestinataire[]\n  formation     Formation?            @relation(fields: [formationId], references: [id])\n  document      Document?             @relation(fields: [documentId], references: [id])\n\n  @@schema(\"ir2f\")\n}\n\nmodel MessageDestinataire {\n  id        String    @id @default(uuid())\n  messageId String\n  userId    String\n  lu        Boolean   @default(false)\n  luAt      DateTime?\n\n  message Message @relation(fields: [messageId], references: [id])\n  user    User    @relation(fields: [userId], references: [id])\n\n  @@unique([messageId, userId])\n  @@schema(\"ir2f\")\n}\n\n// ─── COVOITURAGE ─────────────────────────────────────\n\nmodel Covoiturage {\n  id           String            @id @default(uuid())\n  conducteurId String\n  depart       String\n  destination  String\n  dateDepart   DateTime\n  places       Int\n  statut       StatutCovoiturage @default(OUVERT)\n  commentaire  String?\n  formationId  String?\n  createdAt    DateTime          @default(now())\n\n  conducteur User                  @relation(\"Conducteur\", fields: [conducteurId], references: [id])\n  passagers  CovoituragePassager[]\n  formation  Formation?            @relation(fields: [formationId], references: [id])\n\n  @@schema(\"ir2f\")\n}\n\nmodel CovoituragePassager {\n  id            String   @id @default(uuid())\n  covoiturageId String\n  userId        String\n  createdAt     DateTime @default(now())\n\n  covoiturage Covoiturage @relation(fields: [covoiturageId], references: [id])\n  user        User        @relation(fields: [userId], references: [id])\n\n  @@unique([covoiturageId, userId])\n  @@schema(\"ir2f\")\n}\n\n// ─── ARTICLES / SITE PUBLIC ──────────────────────────\n\nmodel Article {\n  id           String              @id @default(uuid())\n  titre        String\n  slug         String              @unique\n  contenu      String\n  image        String?\n  // Texte court utilisé comme légende quand l'article est partagé sur les réseaux sociaux\n  // (aperçu Facebook, texte pré-rempli du partage natif) — distinct du contenu complet.\n  textePartage String?\n  categorie    CategorieFormation?\n  publie       Boolean             @default(false)\n  auteurId     String\n  createdAt    DateTime            @default(now())\n  updatedAt    DateTime            @updatedAt\n\n  // Sections répétables (photos/vidéos/tableaux/lien de redirection) — voir ArticleSection dans\n  // src/lib/articles-shared.ts, même principe que Formation.programme.\n  sections Json?\n\n  // Suivi des publications officielles sur les réseaux (comptes configurés en variable\n  // d'environnement, voir src/lib/social/accounts.ts — volontairement pas en base pour que ces\n  // identifiants ne soient visibles/modifiables par aucun compte ADMIN, seulement par qui a accès\n  // au déploiement) — { [compteId]: { publishedAt, postId?, error? } }. Distinct du bouton\n  // \"partager\" côté visiteur (qui ne touche pas ce champ) : ici c'est la Ligue qui publie en son nom.\n  reseauxPublies Json?\n\n  auteur User @relation(fields: [auteurId], references: [id])\n\n  @@schema(\"ir2f\")\n}\n\n// ─── CONTENU SITE PUBLIC (accueil / catalogue) ───────\n\n// Icônes disponibles pour les cartes \"Accompagnement Emploi\" de l'accueil\nenum IconeAccompagnement {\n  FINANCEMENT\n  GESTION\n  FORMATION\n  CONTACT\n  DOCUMENT\n  VALIDATION\n\n  @@schema(\"ir2f\")\n}\n\nmodel AccompagnementCard {\n  id          String              @id @default(uuid())\n  titre       String\n  description String\n  icone       IconeAccompagnement @default(FINANCEMENT)\n  ordre       Int                 @default(0)\n  actif       Boolean             @default(true)\n  createdAt   DateTime            @default(now())\n  updatedAt   DateTime            @updatedAt\n\n  @@schema(\"ir2f\")\n}\n\n// Textes éditables de la page d'accueil (une seule ligne, id fixe \"accueil\")\nmodel AccueilContenu {\n  id                    String   @id @default(\"accueil\")\n  bandeauEmploiTitre    String   @default(\"Je souhaite créer un emploi dans mon club\")\n  bandeauEmploiActif    Boolean  @default(true)\n  bandeauBouton1Label   String   @default(\"Je donne mes infos\")\n  bandeauBouton1Type    TypeLien @default(INTERNE)\n  bandeauBouton1Url     String   @default(\"#contact\")\n  bandeauBouton2Label   String   @default(\"En savoir plus\")\n  bandeauBouton2Type    TypeLien @default(INTERNE)\n  bandeauBouton2Url     String   @default(\"/emploi\")\n  accompagnementEyebrow String   @default(\"IR2F vous accompagne\")\n  accompagnementTitre   String   @default(\"Accompagnement Emploi\")\n  contactTitre          String   @default(\"Je souhaite être contacté\")\n  contactSousTitre      String   @default(\"Un conseiller IR2F revient vers vous sous 48h.\")\n  updatedAt             DateTime @updatedAt\n\n  @@schema(\"ir2f\")\n}\n\nmodel FooterContenu {\n  id              String   @id @default(\"footer\")\n  logoFffUrl      String?\n  logoLgefUrl     String?\n  logoQualiopiUrl String?\n  updatedAt       DateTime @updatedAt\n\n  @@schema(\"ir2f\")\n}\n\nmodel StatCle {\n  id        String   @id @default(uuid())\n  valeur    String\n  label     String\n  ordre     Int      @default(0)\n  actif     Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@schema(\"ir2f\")\n}\n\nenum TransitionHero {\n  FADE\n  SLIDE_GAUCHE\n  SLIDE_DROITE\n\n  @@schema(\"ir2f\")\n}\n\nenum AlignementHero {\n  GAUCHE\n  CENTRE\n  DROITE\n\n  @@schema(\"ir2f\")\n}\n\nmodel HeroSlide {\n  id              String         @id @default(uuid())\n  badge           String?\n  titre           String\n  sousTitre       String?\n  logoUrl         String?\n  image           String\n  ctaLabel        String?        @default(\"En savoir plus\")\n  formationId     String?\n  youtubeUrl      String?\n  videoFichierUrl String?\n  alignement      AlignementHero @default(GAUCHE)\n  overlayColor    String         @default(\"#0a162e\")\n  overlayOpacity  Int            @default(60)\n  transition      TransitionHero @default(FADE)\n  dureeAffichage  Int            @default(7)\n  ordre           Int            @default(0)\n  actif           Boolean        @default(true)\n  createdAt       DateTime       @default(now())\n  updatedAt       DateTime       @updatedAt\n\n  formation Formation? @relation(fields: [formationId], references: [id])\n\n  @@schema(\"ir2f\")\n}\n\n// Effet visuel appliqué aux images/vidéos des tuiles et onglets de la page\n// \"Nos Formations\" (voir FormationTuile / FormationOnglet ci-dessous).\nenum EffetVisuel {\n  AUCUN\n  FONDU\n  ZOOM\n  PARALLAXE\n  NOIR_BLANC\n  FLOU\n\n  @@schema(\"ir2f\")\n}\n\n// Police du libellé d'une tuile catégorie — les deux polices du design system.\nenum TuileFont {\n  HEADING\n  BODY\n\n  @@schema(\"ir2f\")\n}\n\n// Les 4 tuiles cliquables en haut de la page \"Nos Formations\" (Éducateurs,\n// Arbitres, Tout Terrain, DEV). Entièrement administrables : image, couleur\n// de fond, opacité et effet visuel.\nmodel FormationTuile {\n  id              String             @id @default(uuid())\n  categorie       CategorieFormation @unique\n  label           String\n  image           String?\n  backgroundColor String             @default(\"#c9a84c\")\n  opacity         Int                @default(100)\n  effetVisuel     EffetVisuel        @default(AUCUN)\n  textColor       String             @default(\"#1a3a6b\")\n  textFont        TuileFont          @default(HEADING)\n  arrowColor      String             @default(\"#1a3a6b\")\n  updatedAt       DateTime           @updatedAt\n\n  @@schema(\"ir2f\")\n}\n\n// Les onglets affichés dans le panneau déroulé d'une catégorie sur la page\n// \"Nos Formations\" (ex : Présentation, Les différents parcours...).\nenum FormationOngletCle {\n  INFO\n  PARCOURS\n  CLUB\n  EDU_PRESENTATION\n  EDU_PRO\n  EDU_BENEVOLE\n  EDU_EQUIVALENCES\n\n  @@schema(\"ir2f\")\n}\n\nmodel FormationOnglet {\n  id              String             @id @default(uuid())\n  categorie       CategorieFormation\n  onglet          FormationOngletCle\n  titre           String?\n  contenu         String?\n  videoUrl        String?\n  videoFichierUrl String?\n  image           String?\n  imageTaille     Int                @default(100)\n  backgroundColor String             @default(\"#f5f7fb\")\n  opacity         Int                @default(100)\n  effetVisuel     EffetVisuel        @default(AUCUN)\n  updatedAt       DateTime           @updatedAt\n\n  // Formation \"vedette\" liée (ex. onglet INFO d'Arbitrage ou de Développement) :\n  // sa durée/format/CPF/FAFA/Bon de Formation et son lien \"Voir la fiche\n  // complète\" s'affichent automatiquement, sans dupliquer ces champs ici.\n  formationVedetteId String?\n  formationVedette   Formation? @relation(fields: [formationVedetteId], references: [id], onDelete: SetNull)\n\n  @@unique([categorie, onglet])\n  @@schema(\"ir2f\")\n}\n\n// Tableaux libres (lignes/colonnes éditables en admin) rattachés à un onglet\n// de la page \"Nos Formations\" — ex. les tableaux d'équivalences de l'onglet\n// EDU_EQUIVALENCES. Rattaché par (categorie, onglet), pas par relation vers\n// FormationOnglet.id, pour ne pas dépendre de l'existence préalable de la\n// ligne FormationOnglet (elle n'est créée qu'au premier enregistrement admin).\nmodel FormationOngletTableau {\n  id        String             @id @default(uuid())\n  categorie CategorieFormation\n  onglet    FormationOngletCle\n  titre     String?\n  entetes   Json\n  lignes    Json\n  ordre     Int                @default(0)\n  actif     Boolean            @default(true)\n\n  @@schema(\"ir2f\")\n}\n\n// Sections libres empilées sous le contenu principal d'un onglet — pour\n// Arbitres, Tout Terrain et Développement (pas Éducateur, dont la structure\n// à onglets/diagramme est trop spécifique). Chaque section porte texte,\n// images, vidéo, tableau et lien, tous optionnels. Rattaché par\n// (categorie, onglet), même raison que FormationOngletTableau ci-dessus.\nmodel FormationOngletSection {\n  id              String             @id @default(uuid())\n  categorie       CategorieFormation\n  onglet          FormationOngletCle\n  titre           String?\n  contenu         String?\n  images          Json // string[]\n  pdfs            Json // { url: string; nom: string }[]\n  videoUrl        String?\n  videoFichierUrl String?\n  tableauTitre    String?\n  tableauEntetes  Json? // string[] | null\n  tableauLignes   Json? // string[][] | null\n  lienLabel       String?\n  lienUrl         String?\n  ordre           Int                @default(0)\n  actif           Boolean            @default(true)\n\n  @@schema(\"ir2f\")\n}\n\n// ─── HERO PAR PAGE ───────────────────────────────────\n\n// Pages statiques disposant d'un bandeau Hero (image de fond) éditable en\n// admin. L'accueil a son propre système de Hero (HeroSlide, carrousel) et\n// n'en fait pas partie ; les pages de détail (fiche formation, article) non\n// plus, elles ont déjà leur propre visuel.\nenum PageCle {\n  FORMATIONS\n  CONTACT\n  EMPLOI\n  ACTUALITES\n  FINANCEMENT\n\n  @@schema(\"ir2f\")\n}\n\nmodel PageHero {\n  id        String   @id @default(uuid())\n  page      PageCle  @unique\n  titre     String\n  sousTitre String?\n  image     String?\n  updatedAt DateTime @updatedAt\n\n  @@schema(\"ir2f\")\n}\n\n// ─── EMPLOI ──────────────────────────────────────────\n\nenum SectionEmploi {\n  FINANCEMENTS\n  GESTION_EMPLOI\n  FORMATION_EMPLOYABILITE\n\n  @@schema(\"ir2f\")\n}\n\nenum TypeDocument {\n  FICHIER\n  LIEN_EXTERNE\n\n  @@schema(\"ir2f\")\n}\n\nmodel DocumentPasserelle {\n  id           String        @id @default(uuid())\n  titre        String\n  url          String\n  type         TypeDocument  @default(LIEN_EXTERNE)\n  section      SectionEmploi\n  dispositifId String?\n  ordre        Int           @default(0)\n  actif        Boolean       @default(true)\n  createdAt    DateTime      @default(now())\n  updatedAt    DateTime      @updatedAt\n\n  dispositif DispositifFinancement? @relation(fields: [dispositifId], references: [id], onDelete: SetNull)\n\n  @@schema(\"ir2f\")\n}\n\nmodel Partenaire {\n  id        String   @id @default(uuid())\n  nom       String\n  logoUrl   String?\n  siteUrl   String?\n  ordre     Int      @default(0)\n  actif     Boolean  @default(true)\n  createdAt DateTime @default(now())\n\n  @@schema(\"ir2f\")\n}\n\nmodel Contact {\n  id        String         @id @default(uuid())\n  nom       String\n  prenom    String?\n  email     String?\n  telephone String?\n  poste     String?\n  section   SectionEmploi?\n  ordre     Int            @default(0)\n  actif     Boolean        @default(true)\n  createdAt DateTime       @default(now())\n\n  @@schema(\"ir2f\")\n}\n\nmodel Video {\n  id              String         @id @default(uuid())\n  titre           String\n  url             String\n  videoFichierUrl String?\n  description     String?\n  section         SectionEmploi?\n  dispositifId    String?\n  ordre           Int            @default(0)\n  actif           Boolean        @default(true)\n  createdAt       DateTime       @default(now())\n\n  dispositif DispositifFinancement? @relation(fields: [dispositifId], references: [id], onDelete: SetNull)\n\n  @@schema(\"ir2f\")\n}\n\nmodel Webinaire {\n  id          String   @id @default(uuid())\n  titre       String\n  description String?\n  date        DateTime\n  lien        String?\n  actif       Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@schema(\"ir2f\")\n}\n\nmodel DispositifFinancement {\n  id                String   @id @default(uuid())\n  titre             String\n  resume            String?\n  contenu           String\n  montantMisEnAvant String?\n  image             String?\n  videoUrl          String?\n  videoFichierUrl   String?\n  ordre             Int      @default(0)\n  actif             Boolean  @default(true)\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  documents DocumentPasserelle[]\n  videos    Video[]\n  referents ReferentEmploi[]\n\n  @@schema(\"ir2f\")\n}\n\nmodel ReferentEmploi {\n  id           String  @id @default(uuid())\n  dispositifId String\n  departement  String\n  referent     String\n  email        String?\n  codeFiche    String?\n  ordre        Int     @default(0)\n  actif        Boolean @default(true)\n\n  dispositif DispositifFinancement @relation(fields: [dispositifId], references: [id], onDelete: Cascade)\n\n  @@schema(\"ir2f\")\n}\n\nenum IconePratique {\n  SOCIETAL\n  COTISATION\n  PARTENARIAT\n  AUTRE\n\n  @@schema(\"ir2f\")\n}\n\nmodel PratiqueEmploiCard {\n  id          String        @id @default(uuid())\n  titre       String\n  description String?\n  icone       IconePratique @default(AUTRE)\n  ordre       Int           @default(0)\n  actif       Boolean       @default(true)\n\n  @@schema(\"ir2f\")\n}\n\nmodel EmploiPageContenu {\n  id                        String   @id @default(\"emploi\")\n  introTexte                String   @default(\"\")\n  introListe                String   @default(\"\")\n  videoCommunauteUrl        String?\n  videoCommunauteFichierUrl String?\n  updatedAt                 DateTime @updatedAt\n\n  @@schema(\"ir2f\")\n}\n\nmodel GestionEmploiContenu {\n  id                            String   @id @default(\"gestion-emploi\")\n  eLearningTitre                String?\n  eLearningTexte                String?\n  eLearningLienLabel            String?\n  eLearningLienUrl              String?\n  creerEmploiTexte              String   @default(\"\")\n  creerEmploiLienLabel          String?\n  creerEmploiLienUrl            String?\n  communauteTitre               String?\n  communauteTexte               String?\n  communauteVideoUrl            String?\n  communauteVideoFichierUrl     String?\n  communauteLienEnSavoirPlusUrl String?\n  communauteLienRejoindreUrl    String?\n  updatedAt                     DateTime @updatedAt\n\n  @@schema(\"ir2f\")\n}\n\nmodel FormationEmployabiliteContenu {\n  id              String   @id @default(\"formation-employabilite\")\n  introTexte      String?\n  indicateursNote String?\n  updatedAt       DateTime @updatedAt\n\n  @@schema(\"ir2f\")\n}\n\n// ─── FINANCEMENT (aides individuelles à la formation) ─\n\nmodel DispositifFormation {\n  id                String   @id @default(uuid())\n  titre             String\n  resume            String?\n  contenu           String\n  montantMisEnAvant String?\n  image             String?\n  videoUrl          String?\n  videoFichierUrl   String?\n  ordre             Int      @default(0)\n  actif             Boolean  @default(true)\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  liens    LienFormation[]\n  contacts ContactFormation[]\n  tableaux DispositifFormationTableau[]\n\n  @@schema(\"ir2f\")\n}\n\nmodel LienFormation {\n  id           String  @id @default(uuid())\n  dispositifId String\n  label        String\n  url          String\n  ordre        Int     @default(0)\n  actif        Boolean @default(true)\n\n  dispositif DispositifFormation @relation(fields: [dispositifId], references: [id], onDelete: Cascade)\n\n  @@schema(\"ir2f\")\n}\n\nmodel ContactFormation {\n  id           String  @id @default(uuid())\n  dispositifId String\n  zone         String?\n  nom          String\n  telephone    String?\n  email        String?\n  ordre        Int     @default(0)\n  actif        Boolean @default(true)\n\n  dispositif DispositifFormation @relation(fields: [dispositifId], references: [id], onDelete: Cascade)\n\n  @@schema(\"ir2f\")\n}\n\nmodel DispositifFormationTableau {\n  id           String  @id @default(uuid())\n  dispositifId String\n  titre        String?\n  entetes      Json\n  lignes       Json\n  ordre        Int     @default(0)\n  actif        Boolean @default(true)\n\n  dispositif DispositifFormation @relation(fields: [dispositifId], references: [id], onDelete: Cascade)\n\n  @@schema(\"ir2f\")\n}\n\n// ─── DOCUMENTATION (page publique /documentation) ─────\n\nenum DocumentationFormat {\n  PDF\n  DOCX\n\n  @@schema(\"ir2f\")\n}\n\nmodel DocumentationGroupe {\n  id        String                 @id @default(uuid())\n  titre     String\n  ordre     Int                    @default(0)\n  documents DocumentationFichier[]\n\n  @@schema(\"ir2f\")\n}\n\nmodel DocumentationFichier {\n  id          String              @id @default(uuid())\n  groupeId    String\n  titre       String\n  description String?\n  url         String\n  format      DocumentationFormat\n  ordre       Int                 @default(0)\n\n  groupe DocumentationGroupe @relation(fields: [groupeId], references: [id], onDelete: Cascade)\n\n  @@schema(\"ir2f\")\n}\n\n// ─── POP-UP D'ACCUEIL ────────────────────────────────\n\n// EDITO : le mot du président, affiché avec sa photo et sa signature. ANNONCE : campagne ponctuelle\n// (actualité, événement...) affichée pendant une période donnée, avec image/vidéo et lien au choix.\nenum TypePopup {\n  EDITO\n  ANNONCE\n\n  @@schema(\"ir2f\")\n}\n\n// Un visiteur qui a fermé un pop-up ne le revoit plus (mémorisé par id côté navigateur, voir\n// popup-shared.ts) — publier un nouveau pop-up (nouvel id) le fait donc réapparaître pour tout le\n// monde, ce qui permet d'enchaîner les annonces au cours de l'année sans rouvrir l'édito à chaque fois.\nmodel Popup {\n  id    String    @id @default(uuid())\n  type  TypePopup @default(ANNONCE)\n  actif Boolean   @default(false)\n\n  // Photo en haut à gauche du pop-up (le président pour un édito, un visuel pour une annonce).\n  image String?\n  titre String\n  texte String\n\n  // Édito uniquement : identité + signature du président sous le mot.\n  auteurNom      String?\n  auteurFonction String?\n  signatureUrl   String?\n\n  // Annonce uniquement : vidéo et/ou lien (vers une page interne — tableau, formation... — ou externe).\n  youtubeUrl      String?\n  videoFichierUrl String?\n  lienLabel       String?\n  lienUrl         String?\n  lienType        TypeLien? @default(INTERNE)\n\n  // Délai avant ouverture automatique à l'arrivée sur le site, et fenêtre de diffusion (annonces).\n  delaiAffichage Int       @default(4)\n  dateDebut      DateTime?\n  dateFin        DateTime?\n  ordre          Int       @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@schema(\"ir2f\")\n}\n\n// ─── TUTORIELS D'INSCRIPTION ─────────────────────────\n\nenum TutorielInscriptionCible {\n  STAGIAIRE\n  CLUB\n\n  @@schema(\"ir2f\")\n}\n\nenum TutorielInscriptionMode {\n  LIEN\n  PDF\n  VIDEO\n\n  @@schema(\"ir2f\")\n}\n\n// Petit lien discret affiché sous les boutons d'inscription FFF (\"Je m'inscris\" / \"Le club\n// m'inscrit !\") sur la fiche publique d'une formation. Propre à chaque formation (au plus un\n// enregistrement par formation et par cible STAGIAIRE/CLUB) ; le lien ne s'affiche que si un\n// tutoriel est configuré pour cette cible sur cette formation.\nmodel TutorielInscription {\n  id          String                   @id @default(uuid())\n  formationId String\n  cible       TutorielInscriptionCible\n  mode        TutorielInscriptionMode  @default(LIEN)\n\n  // Mode LIEN : ouvre directement cette URL dans un nouvel onglet.\n  lienUrl String?\n\n  // Mode PDF : fichier affiché et téléchargeable dans une pop-up.\n  pdfUrl String?\n\n  // Mode VIDEO : lien YouTube et/ou fichier vidéo uploadé, affiché dans une pop-up (fichier\n  // prioritaire sur YouTube si les deux sont renseignés). Téléchargeable seulement si fichier.\n  youtubeUrl      String?\n  videoFichierUrl String?\n\n  updatedAt DateTime @updatedAt\n\n  formation Formation @relation(fields: [formationId], references: [id], onDelete: Cascade)\n\n  @@unique([formationId, cible])\n  @@schema(\"ir2f\")\n}\n"
}

